import { Router } from "express";
import { asyncHandler } from "../../../shared/http/async-handler.js";
import { ensureAuthenticated, ensurePermissions } from "../../auth/middlewares/auth.middleware.js";
import { ContabilidadeController } from "../controllers/contabilidade.controller.js";
const controller = new ContabilidadeController();
export const contabilidadeRoutes = Router();
const permissoesLeitura = ["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"];
const permissoesEscrita = ["ADMINISTRADOR", "OPERADOR"];
const permissaoExclusao = ["ADMINISTRADOR"];
contabilidadeRoutes.get("/contas-bancarias", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarContasBancarias.bind(controller)));
contabilidadeRoutes.post("/contas-bancarias", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarContaBancaria.bind(controller)));
contabilidadeRoutes.put("/contas-bancarias/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarContaBancaria.bind(controller)));
contabilidadeRoutes.delete("/contas-bancarias/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerContaBancaria.bind(controller)));
contabilidadeRoutes.get("/categorias", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarCategorias.bind(controller)));
contabilidadeRoutes.post("/categorias", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarCategoria.bind(controller)));
contabilidadeRoutes.put("/categorias/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarCategoria.bind(controller)));
contabilidadeRoutes.delete("/categorias/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerCategoria.bind(controller)));
contabilidadeRoutes.get("/centros-custo", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarCentrosCusto.bind(controller)));
contabilidadeRoutes.post("/centros-custo", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarCentroCusto.bind(controller)));
contabilidadeRoutes.put("/centros-custo/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarCentroCusto.bind(controller)));
contabilidadeRoutes.delete("/centros-custo/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerCentroCusto.bind(controller)));
contabilidadeRoutes.get("/lancamentos", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarLancamentos.bind(controller)));
contabilidadeRoutes.post("/lancamentos", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarLancamento.bind(controller)));
contabilidadeRoutes.put("/lancamentos/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarLancamento.bind(controller)));
contabilidadeRoutes.patch("/lancamentos/:id/status", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarSituacaoLancamento.bind(controller)));
contabilidadeRoutes.post("/lancamentos/:id/pagamento", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.pagarLancamento.bind(controller)));
contabilidadeRoutes.patch("/lancamentos/:id/estorno", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.estornarLancamento.bind(controller)));
contabilidadeRoutes.delete("/lancamentos/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerLancamento.bind(controller)));
contabilidadeRoutes.get("/movimentacoes", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarMovimentacoes.bind(controller)));
contabilidadeRoutes.post("/movimentacoes", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarMovimentacao.bind(controller)));
contabilidadeRoutes.put("/movimentacoes/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarMovimentacao.bind(controller)));
contabilidadeRoutes.delete("/movimentacoes/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerMovimentacao.bind(controller)));
contabilidadeRoutes.get("/transferencias", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarTransferencias.bind(controller)));
contabilidadeRoutes.post("/transferencias", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarTransferencia.bind(controller)));
contabilidadeRoutes.patch("/transferencias/:id/estorno", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.estornarTransferencia.bind(controller)));
contabilidadeRoutes.get("/conciliacoes", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarConciliacoes.bind(controller)));
contabilidadeRoutes.post("/conciliacoes", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarConciliacao.bind(controller)));
contabilidadeRoutes.patch("/conciliacoes/:id/situacao", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarSituacaoConciliacao.bind(controller)));
contabilidadeRoutes.get("/historico", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarHistorico.bind(controller)));
contabilidadeRoutes.get("/fechamentos-mensais", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarFechamentosMensais.bind(controller)));
contabilidadeRoutes.post("/fechar-mes", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.fecharMes.bind(controller)));
contabilidadeRoutes.get("/compras-integradas", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarComprasIntegradas.bind(controller)));
contabilidadeRoutes.post("/compras-integradas/:id/gerar-obrigacao", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.gerarObrigacaoFinanceiraPorCompra.bind(controller)));
contabilidadeRoutes.get("/emendas", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarEmendas.bind(controller)));
contabilidadeRoutes.post("/emendas", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarEmenda.bind(controller)));
contabilidadeRoutes.patch("/emendas/:id/status", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizarStatusEmenda.bind(controller)));
